<script lang="ts">import{materializeBatch}from'../template/materialize.js';import{layoutBatch,materializeZonePages}from'../zones.js';import type{LabelDocument}from'../model.js';import type{PrinterDefinition,PrinterSdk,PrintRoute}from'../print/types.js';export let document:LabelDocument;export let sdk:PrinterSdk;export let route:PrintRoute|undefined=undefined;export let printer:PrinterDefinition|undefined=undefined;let copies=1;let zone='all';let status='';$:zones=zone==='all'?(document.media.zones??[]):(document.media.zones??[]).filter(item=>item.id===zone);$:placements=zones.length?layoutBatch(document.template?.records.length??0,zones):[];async function pdf(){try{const docs=zones.length?materializeZonePages(document,zones):materializeBatch(document);if(!docs.length)throw new Error('Import CSV records first.');const data=await sdk.exportPdf(docs.flatMap(doc=>Array.from({length:copies},()=>doc)));const a=globalThis.document.createElement('a');a.href=URL.createObjectURL(new Blob([data.slice().buffer],{type:'application/pdf'}));a.download='label-batch.pdf';a.click();URL.revokeObjectURL(a.href);status=`Exported ${docs.length*copies} labels.`}catch(error){status=String(error)}}async function print(){if(!route||!printer)return;const docs=zones.length?materializeZonePages(document,zones):materializeBatch(document);let completed=0;for(const doc of docs){const result=await route.print({document:doc,printer,copies});if(result.outcome!=='completed'){status=`Stopped after ${completed}: ${result.outcome}. Inspect printer before retrying.`;return}completed++}status=`Printed ${completed} records.`}</script>
<section><h2>Batch</h2><p>{document.template?.records.length??0} records</p><label>Batch zone layout<select bind:value={zone}><option value="all">Fill all zones by page</option>{#each document.media.zones??[] as item}<option value={item.id}>Only {item.name}</option>{/each}</select></label>{#if placements.length}<p class="placements">{placements.slice(0,8).map(item=>`#${item.record+1}→page ${item.page+1}/${item.zone}`).join(' · ')}</p>{:else if document.template?.records.length}<p>Add a media zone to define batch placement.</p>{/if}<label>Copies per record<input type="number" min="1" max="100" bind:value={copies}></label><button on:click={pdf}>Export batch PDF</button><button on:click={print} disabled={!route||!printer||!document.template?.records.length}>Print batch</button><p aria-live="polite">{status}</p></section>
<style>section{padding:.75rem;border-top:1px solid var(--mble-border,#ddd)}h2{font-size:.8rem;text-transform:uppercase}label{display:flex;flex-direction:column;font-size:.75rem}.placements{font-size:.7rem}</style>
